import type { LitiConfig } from 'liti/adapter'
import { physicalSchema } from './schema'

/** Emit source for the selected ORM owner without loading its builders or driver. */
export function emitDrizzleSchema(config: LitiConfig, modules: { builders: string; sql: string }): string {
    const result = [
        '// Generated by liti generate. Edit liti.config.ts, then run liti generate.',
        `import { sql } from ${JSON.stringify(modules.sql)}`,
        `import { index, integer, primaryKey, real, sqliteTable, text, uniqueIndex } from ${JSON.stringify(modules.builders)}`,
    ]
    for (const [name, table] of Object.entries(physicalSchema(config))) {
        const columns = Object.entries(table.columns).map(([key, column]) => {
            let value = `${column.type}(${JSON.stringify(column.name)}${column.mode ? `, { mode: ${JSON.stringify(column.mode)} }` : ''})`
            if (column.primary) value += '.primaryKey()'
            if (column.notNull) value += '.notNull()'
            if (column.default !== undefined) value += `.default(${JSON.stringify(column.default)})`
            if (column.references) {
                const { table: target, column: targetColumn, onDelete } = column.references
                value += `.references(() => ${target}[${JSON.stringify(targetColumn)}], { onDelete: ${JSON.stringify(onDelete)} })`
            }
            return `  ${JSON.stringify(key)}: ${value}`
        })
        const indexes = (table.indexes ?? []).map((index) => {
            const values = index.columns.map((key) => `table[${JSON.stringify(key)}]`).join(', ')
            return `  ${index.unique ? 'uniqueIndex' : 'index'}(${JSON.stringify(index.name)}).on(${values})${index.where ? `.where(sql.raw(${JSON.stringify(index.where)}))` : ''}`
        })
        if (table.primaryKey)
            indexes.unshift(
                `  primaryKey({ columns: [${table.primaryKey.map((key) => `table[${JSON.stringify(key)}]`).join(', ')}] })`,
            )
        result.push(
            `export const ${name} = sqliteTable(${JSON.stringify(table.name)}, {\n${columns.join(',\n')}\n}${indexes.length ? `, (table) => [\n${indexes.join(',\n')}\n]` : ''})`,
        )
    }
    return result.join('\n\n') + '\n'
}
